import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { appendPolicy, describe, fromPolicyJson, isExpired, removeSpan, replaceSpan, sentenceText, suggestId, toCedar, validRuleId, type Rule } from "../src/rules.ts";

interface Fixture {
  name: string;
  rule: Rule | null;
  cedar: string;
  json: unknown;
}

// Generated by scripts/gen-rule-fixtures.ts; the JSON is the real engine's
// parse of each Cedar text (plugins/pkg/core/authz/console_fixtures_test.go
// also validates every one against the schema).
const fixtures = JSON.parse(readFileSync(new URL("./fixtures/rules.json", import.meta.url), "utf8")) as Fixture[];

test("fixtures are present and filled by the engine", () => {
  assert.ok(fixtures.length >= 10);
  for (const f of fixtures) assert.ok(f.json, `${f.name}: missing engine JSON (run the Go fixture test with -update)`);
});

for (const f of fixtures.filter((x) => x.rule)) {
  test(`round trip: ${f.name}`, () => {
    assert.equal(toCedar(f.rule!), f.cedar, "builder output drifted from the validated fixture");
    assert.deepEqual(fromPolicyJson(f.json), f.rule);
  });
}

for (const f of fixtures.filter((x) => !x.rule)) {
  test(`custom stays custom: ${f.name}`, () => {
    assert.equal(fromPolicyJson(f.json), null);
  });
}

test("the 4Orbit template reads as plain sentences", () => {
  const rule: Rule = { id: "x", effect: "permit", who: { kind: "role", id: "developer" }, can: ["kms.Encrypt"], on: { kind: "keys", ids: ["demo-key"] }, until: 1800000000 };
  const text = sentenceText(describe(rule));
  assert.match(text, /^Agents with the developer role can encrypt with demo-key, until .*2027.*\.$/);
  const block: Rule = { id: "y", effect: "forbid", who: { kind: "anyAgent" }, can: [], on: { kind: "tag", key: "env", value: "prod" } };
  assert.equal(sentenceText(describe(block)), "Any agent can never do anything with keys tagged env = prod.");
  const multi: Rule = { id: "z", effect: "permit", who: { kind: "agent", id: "ci" }, can: ["kms.Sign", "read", "rotate"], on: { kind: "keys", ids: ["a", "b", "c"] } };
  assert.equal(sentenceText(describe(multi)), "ci can sign, view info or rotate on a, b and c.");
});

test("expiry", () => {
  const r: Rule = { id: "x", effect: "permit", who: { kind: "anyone" }, can: [], on: { kind: "anyKey" }, until: 100 };
  assert.equal(isExpired(r, 99), false);
  assert.equal(isExpired(r, 100), true);
  assert.equal(isExpired({ ...r, until: undefined }, 1e12), false);
});

test("ids: suggestions are readable, unique and valid", () => {
  const base = { effect: "permit" as const, who: { kind: "role" as const, id: "developer" }, can: ["kms.Encrypt"], on: { kind: "keys" as const, ids: ["dev-key"] } };
  const taken = new Set(["developer-encrypt-dev-key"]);
  const id = suggestId(base, taken);
  assert.equal(id, "developer-encrypt-dev-key-2");
  assert.ok(validRuleId(id));
  assert.equal(suggestId({ ...base, effect: "forbid", who: { kind: "anyAgent" }, can: [], on: { kind: "tag", key: "env", value: "prod" } }, new Set()), "deny-agents-all-env-prod");
  assert.ok(!validRuleId("platform.mine"));
  assert.ok(!validRuleId("has space"));
});

test("text edits: replace, remove and append keep the rest intact", () => {
  const src = "// keep me\n@id(\"a\") permit (principal, action, resource);\n\n@id(\"b\") forbid (principal, action, resource);\n";
  const aStart = src.indexOf("@id(\"a\")");
  const aEnd = src.indexOf(";", aStart) + 1;
  assert.equal(replaceSpan(src, aStart, aEnd, "X;"), "// keep me\nX;\n\n@id(\"b\") forbid (principal, action, resource);\n");
  assert.equal(removeSpan(src, aStart, aEnd), "// keep me\n@id(\"b\") forbid (principal, action, resource);\n");
  assert.equal(appendPolicy("", "P;"), "P;\n");
  assert.equal(appendPolicy("A;\n\n\n", "P;"), "A;\n\nP;\n");
});

test("GitHub rules name repositories and reject broad or incompatible scopes", () => {
  const rule: Rule = { id: "developer-create-issues", effect: "permit", who: { kind: "role", id: "developer" }, can: ["github.issue.Create"], on: { kind: "repositories", ids: ["4-Orbit/orbitport-issue-test"] } };
  assert.equal(sentenceText(describe(rule)), "Agents with the developer role can create issues in 4-Orbit/orbitport-issue-test.");
  assert.match(toCedar(rule), /resource == Repository::"4-Orbit\/orbitport-issue-test"/);
  for (const invalid of [
    { ...rule, on: { kind: "repositories" as const, ids: [] } },
    { ...rule, on: { kind: "repositories" as const, ids: ["owner/../repo"] } },
    { ...rule, can: [] },
    { ...rule, can: ["kms.Encrypt"] },
    { ...rule, can: ["github.issue.Close"] },
  ]) assert.throws(() => toCedar(invalid), /GitHub action/);
  const fixture = fixtures.find((f) => f.name === "github-developer-create-issues")!;
  const unsupported = structuredClone(fixture.json) as { action: unknown };
  unsupported.action = { op: "==", entity: { type: "Action", id: "github.issue.Close" } };
  assert.equal(fromPolicyJson(unsupported), null, "unsupported actions stay custom");
});
